# Inspect task description in bluffbench
prompt_text <- ""
if (exists("tsk")) {
  prompt_text <- capture.output(str(tsk))
} else if (exists("task")) {
  prompt_text <- capture.output(str(task))
}

ggplot() +
  annotate("text", x = 0, y = seq_along(prompt_text)[1:min(15, length(prompt_text))], 
           label = rev(prompt_text[1:min(15, length(prompt_text))]), hjust = 0, family = "mono", size = 3) +
  xlim(0, 10) +
  theme_void()

